=== FILE: sync_fifo.v ===
`timescale 1ns/1ps
// sync_fifo: parameterizable single-clock FIFO, first-word fall-through.
// Implements interface_spec.md per microarchitecture.md:
//  - explicit occupancy counter `count_q` (works for any DEPTH >= 2)
//  - pointers wrap by compare against LAST = DEPTH-1, not by overflow
//  - wr_acc = wr_en & !full, rd_acc = rd_en & !empty (drop/ignore policy)
//  - rd_data = mem[rd_ptr_q] (combinational read, 1-cycle write-to-read)
//  - rst_n synchronous, active low; clears pointers and count, not storage
module sync_fifo #(
  parameter integer DEPTH = 8,
  parameter integer WIDTH = 8
) (
  input  wire                       clk,
  input  wire                       rst_n,
  input  wire                       wr_en,
  input  wire [WIDTH-1:0]           wr_data,
  output wire                       full,
  input  wire                       rd_en,
  output wire [WIDTH-1:0]           rd_data,
  output wire                       empty,
  output wire [$clog2(DEPTH+1)-1:0] count
);

  localparam integer AW       = $clog2(DEPTH);
  localparam integer CW       = $clog2(DEPTH + 1);
  localparam integer ONE      = 1;
  localparam integer DEPTH_M1 = DEPTH - 1;
  localparam [AW-1:0] LAST    = DEPTH_M1[AW-1:0];
  localparam [AW-1:0] A_ONE   = ONE[AW-1:0];
  localparam [CW-1:0] C_ONE   = ONE[CW-1:0];
  localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];

  // Storage: datapath, not reset, written only outside reset.
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  reg [AW-1:0] wr_ptr_q;
  reg [AW-1:0] wr_ptr_d;
  reg [AW-1:0] rd_ptr_q;
  reg [AW-1:0] rd_ptr_d;
  reg [CW-1:0] count_q;
  reg [CW-1:0] count_d;

  wire wr_acc;
  wire rd_acc;

  // Flags are compares on a register: no combinational path from inputs.
  assign full    = (count_q == DEPTH_C);
  assign empty   = (count_q == {CW{1'b0}});
  assign count   = count_q;
  assign wr_acc  = wr_en & ~full;
  assign rd_acc  = rd_en & ~empty;
  assign rd_data = mem[rd_ptr_q];

  // Next-state logic.
  always @* begin
    wr_ptr_d = wr_ptr_q;
    rd_ptr_d = rd_ptr_q;
    count_d  = count_q;
    if (wr_acc) begin
      if (wr_ptr_q == LAST) wr_ptr_d = {AW{1'b0}};
      else                  wr_ptr_d = wr_ptr_q + A_ONE;
    end
    if (rd_acc) begin
      if (rd_ptr_q == LAST) rd_ptr_d = {AW{1'b0}};
      else                  rd_ptr_d = rd_ptr_q + A_ONE;
    end
    if (wr_acc && !rd_acc)      count_d = count_q + C_ONE;
    else if (rd_acc && !wr_acc) count_d = count_q - C_ONE;
    else                        count_d = count_q;
  end

  // State registers: synchronous active-low reset.
  always @(posedge clk) begin
    if (!rst_n) begin
      wr_ptr_q <= {AW{1'b0}};
      rd_ptr_q <= {AW{1'b0}};
      count_q  <= {CW{1'b0}};
    end else begin
      wr_ptr_q <= wr_ptr_d;
      rd_ptr_q <= rd_ptr_d;
      count_q  <= count_d;
    end
  end

  // Storage write.
  always @(posedge clk) begin
    if (rst_n && wr_acc) begin
      mem[wr_ptr_q] <= wr_data;
    end
  end

`ifdef FORMAL
  reg f_past_valid = 1'b0;
  always @(posedge clk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume(!rst_n);
  end

  // One solver-chosen slot, tracked with a shadow copy.
  (* anyconst *) reg [AW-1:0] f_addr;
  always @(*) assume(f_addr <= LAST);

  reg [WIDTH-1:0] f_data;
  reg             f_written = 1'b0;
  always @(posedge clk) begin
    if (rst_n && wr_acc && (wr_ptr_q == f_addr)) begin
      f_data    <= wr_data;
      f_written <= 1'b1;
    end
  end

  wire [31:0] f_wsum = rd_ptr_q + count_q;
  wire [31:0] f_wexp = (f_wsum >= DEPTH) ? (f_wsum - DEPTH) : f_wsum;
  wire [31:0] f_dist = (f_addr >= rd_ptr_q) ? (f_addr - rd_ptr_q)
                                            : (f_addr + DEPTH - rd_ptr_q);
  wire        f_in_use = (f_dist < count_q);

  always @(*) begin
    if (f_past_valid) begin
      assert(count_q <= DEPTH_C);
      assert(wr_ptr_q <= LAST);
      assert(rd_ptr_q <= LAST);
      assert(full  == (count_q == DEPTH_C));
      assert(empty == (count_q == {CW{1'b0}}));
      assert(!(full && empty));
      assert(wr_ptr_q == f_wexp);
      if (f_in_use) assert(f_written);
      if (f_written) assert(mem[f_addr] == f_data);
      if (!empty && (rd_ptr_q == f_addr)) assert(rd_data == f_data);
    end
  end

  always @(posedge clk) begin
    if (f_past_valid && !$past(rst_n)) begin
      assert(count_q == {CW{1'b0}});
      assert(wr_ptr_q == {AW{1'b0}});
      assert(rd_ptr_q == {AW{1'b0}});
    end
    if (f_past_valid && $past(rst_n)) begin
      if ($past(wr_acc) && !$past(rd_acc))
        assert(count_q == $past(count_q) + C_ONE);
      else if (!$past(wr_acc) && $past(rd_acc))
        assert(count_q == $past(count_q) - C_ONE);
      else
        assert(count_q == $past(count_q));
      if ($past(full))  assert(wr_ptr_q == $past(wr_ptr_q));
      if ($past(empty)) assert(rd_ptr_q == $past(rd_ptr_q));
      if ($past(full) && !$past(rd_en))  assert(count_q == $past(count_q));
      if ($past(empty) && !$past(wr_en)) assert(count_q == {CW{1'b0}});
    end
  end

  // Covers: the proof must not be vacuous.
  reg f_was_full = 1'b0;
  always @(posedge clk) begin
    if (!rst_n)    f_was_full <= 1'b0;
    else if (full) f_was_full <= 1'b1;
  end

  always @(*) begin
    if (f_past_valid && rst_n) cover(full);
    cover(f_past_valid && rst_n && f_was_full && empty);
    cover(f_past_valid && rst_n && full && wr_en);
    cover(f_past_valid && rst_n && wr_en && rd_en && !full && !empty);
    cover(f_past_valid && f_written && !empty && (rd_ptr_q == f_addr));
  end
`endif

endmodule
=== END FILE ===
