`timescale 1ns/1ps
// Self-checking testbench for sync_fifo.
// Two DUTs on the same stimulus: A = DEPTH 8 x WIDTH 8, B = DEPTH 5 x WIDTH 12.
// Every cycle, full/empty/count/rd_data are checked against a reference queue.
// Check ids: A 1..5, B 11..15. Coverage goal ids: A 101..110, B 201..210
//   +1 full reached          +2 write while full     +3 drained to empty after full
//   +4 read while empty      +5 wr+rd when empty     +6 wr+rd when full
//   +7 wr+rd in between      +8 write pointer wrap   +9 read pointer wrap
//   +10 reset during traffic
module sync_fifo_tb;

  reg         clk;
  reg         rst_n;
  reg         wr_en;
  reg         rd_en;
  reg  [11:0] wdata;

  wire        a_full;
  wire        a_empty;
  wire [7:0]  a_rd_data;
  wire [3:0]  a_count;
  wire        b_full;
  wire        b_empty;
  wire [11:0] b_rd_data;
  wire [2:0]  b_count;

  sync_fifo #(.DEPTH(8), .WIDTH(8)) dut_a (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wdata[7:0]),
    .full(a_full), .rd_en(rd_en), .rd_data(a_rd_data), .empty(a_empty),
    .count(a_count)
  );

  sync_fifo #(.DEPTH(5), .WIDTH(12)) dut_b (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wdata),
    .full(b_full), .rd_en(rd_en), .rd_data(b_rd_data), .empty(b_empty),
    .count(b_count)
  );

  // Reference queues.
  reg [7:0]  ma_q [0:15];
  reg [3:0]  ma_head;
  reg [3:0]  ma_cnt;
  reg        a_seen_full;
  reg [11:0] mb_q [0:15];
  reg [3:0]  mb_head;
  reg [2:0]  mb_cnt;
  reg        b_seen_full;
  reg [3:0]  idx;
  reg        acc_w;
  reg        acc_r;

  integer passed;
  integer failed;
  integer a_wr_ep;
  integer a_rd_ep;
  integer b_wr_ep;
  integer b_rd_ep;
  integer a_cov [0:15];
  integer b_cov [0:15];
  integer i;
  integer k;
  integer phase;

  reg [31:0]      rng;
  reg [8:0]       wthr;
  reg [8:0]       rthr;
  reg [8*64-1:0]  nonce;

  initial clk = 1'b0;
  always #5 clk = ~clk;

  task check_bit;
    input   actual;
    input   expected;
    input integer id;
    begin
      if (actual === expected) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("check %0d failed: got %b expected %b at %0t", id, actual, expected, $time);
      end
    end
  endtask

  task check_vec;
    input [15:0] actual;
    input [15:0] expected;
    input integer id;
    begin
      if (actual === expected) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("check %0d failed: got %h expected %h at %0t", id, actual, expected, $time);
      end
    end
  endtask

  task cover_goal;
    input integer hits;
    input integer id;
    begin
      if (hits > 0) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("coverage goal %0d never reached", id);
      end
    end
  endtask

  task next_rand;
    begin
      rng = rng ^ (rng << 13);
      rng = rng ^ (rng >> 17);
      rng = rng ^ (rng << 5);
    end
  endtask

  // Sampled before the edge: model state equals DUT state here.
  task sample_coverage;
    begin
      if (!rst_n) begin
        if ((ma_cnt != 4'd0) && (wr_en || rd_en)) a_cov[10] = a_cov[10] + 1;
        if ((mb_cnt != 3'd0) && (wr_en || rd_en)) b_cov[10] = b_cov[10] + 1;
      end else begin
        if (wr_en && (ma_cnt == 4'd8)) a_cov[2] = a_cov[2] + 1;
        if (rd_en && (ma_cnt == 4'd0)) a_cov[4] = a_cov[4] + 1;
        if (wr_en && rd_en) begin
          if (ma_cnt == 4'd0)      a_cov[5] = a_cov[5] + 1;
          else if (ma_cnt == 4'd8) a_cov[6] = a_cov[6] + 1;
          else                     a_cov[7] = a_cov[7] + 1;
        end
        if (wr_en && (mb_cnt == 3'd5)) b_cov[2] = b_cov[2] + 1;
        if (rd_en && (mb_cnt == 3'd0)) b_cov[4] = b_cov[4] + 1;
        if (wr_en && rd_en) begin
          if (mb_cnt == 3'd0)      b_cov[5] = b_cov[5] + 1;
          else if (mb_cnt == 3'd5) b_cov[6] = b_cov[6] + 1;
          else                     b_cov[7] = b_cov[7] + 1;
        end
      end
    end
  endtask

  // Applied at the rising edge, with the inputs the DUTs sample there.
  task model_update;
    begin
      if (!rst_n) begin
        ma_head = 4'd0; ma_cnt = 4'd0; a_seen_full = 1'b0; a_wr_ep = 0; a_rd_ep = 0;
        mb_head = 4'd0; mb_cnt = 3'd0; b_seen_full = 1'b0; b_wr_ep = 0; b_rd_ep = 0;
      end else begin
        // DUT A, DEPTH 8
        acc_w = wr_en && (ma_cnt != 4'd8);
        acc_r = rd_en && (ma_cnt != 4'd0);
        if (acc_r) begin
          ma_head = ma_head + 4'd1;
          ma_cnt  = ma_cnt - 4'd1;
          a_rd_ep = a_rd_ep + 1;
          if (a_rd_ep == 8) a_cov[9] = a_cov[9] + 1;
        end
        if (acc_w) begin
          idx = ma_head + ma_cnt;
          ma_q[idx] = wdata[7:0];
          ma_cnt  = ma_cnt + 4'd1;
          a_wr_ep = a_wr_ep + 1;
          if (a_wr_ep == 8) a_cov[8] = a_cov[8] + 1;
        end
        if (ma_cnt == 4'd8) begin
          a_cov[1] = a_cov[1] + 1;
          a_seen_full = 1'b1;
        end
        if ((ma_cnt == 4'd0) && a_seen_full) begin
          a_cov[3] = a_cov[3] + 1;
          a_seen_full = 1'b0;
        end
        // DUT B, DEPTH 5
        acc_w = wr_en && (mb_cnt != 3'd5);
        acc_r = rd_en && (mb_cnt != 3'd0);
        if (acc_r) begin
          mb_head = mb_head + 4'd1;
          mb_cnt  = mb_cnt - 3'd1;
          b_rd_ep = b_rd_ep + 1;
          if (b_rd_ep == 5) b_cov[9] = b_cov[9] + 1;
        end
        if (acc_w) begin
          idx = mb_head + {1'b0, mb_cnt};
          mb_q[idx] = wdata;
          mb_cnt  = mb_cnt + 3'd1;
          b_wr_ep = b_wr_ep + 1;
          if (b_wr_ep == 5) b_cov[8] = b_cov[8] + 1;
        end
        if (mb_cnt == 3'd5) begin
          b_cov[1] = b_cov[1] + 1;
          b_seen_full = 1'b1;
        end
        if ((mb_cnt == 3'd0) && b_seen_full) begin
          b_cov[3] = b_cov[3] + 1;
          b_seen_full = 1'b0;
        end
      end
    end
  endtask

  task check_outputs;
    begin
      check_bit(a_full,  (ma_cnt == 4'd8), 1);
      check_bit(a_empty, (ma_cnt == 4'd0), 2);
      check_vec({12'd0, a_count}, {12'd0, ma_cnt}, 3);
      if (ma_cnt != 4'd0) check_vec({8'd0, a_rd_data}, {8'd0, ma_q[ma_head]}, 4);
      check_bit(a_full & a_empty, 1'b0, 5);
      check_bit(b_full,  (mb_cnt == 3'd5), 11);
      check_bit(b_empty, (mb_cnt == 3'd0), 12);
      check_vec({13'd0, b_count}, {13'd0, mb_cnt}, 13);
      if (mb_cnt != 3'd0) check_vec({4'd0, b_rd_data}, {4'd0, mb_q[mb_head]}, 14);
      check_bit(b_full & b_empty, 1'b0, 15);
    end
  endtask

  task do_cycle;
    input        t_rst_n;
    input        t_wr;
    input        t_rd;
    input [11:0] t_data;
    begin
      @(negedge clk);
      rst_n = t_rst_n;
      wr_en = t_wr;
      rd_en = t_rd;
      wdata = t_data;
      sample_coverage;
      @(posedge clk);
      model_update;
      #1;
      check_outputs;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    wr_en = 1'b0;
    rd_en = 1'b0;
    wdata = 12'd0;
    passed = 0;
    failed = 0;
    ma_head = 4'd0; ma_cnt = 4'd0; a_seen_full = 1'b0;
    mb_head = 4'd0; mb_cnt = 3'd0; b_seen_full = 1'b0;
    a_wr_ep = 0; a_rd_ep = 0; b_wr_ep = 0; b_rd_ep = 0;
    idx = 4'd0; acc_w = 1'b0; acc_r = 1'b0;
    phase = 0;
    for (k = 0; k < 16; k = k + 1) begin
      a_cov[k] = 0;
      b_cov[k] = 0;
    end
    rng  = 32'h2545F491;
    wthr = 9'd128;
    rthr = 9'd128;
    nonce = {512{1'b0}};
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
      $display("sync_fifo_tb: no +nirmaan_nonce given");

    // P0: reset with requests asserted (must be ignored).
    do_cycle(1'b0, 1'b1, 1'b1, 12'h0A5);
    do_cycle(1'b0, 1'b1, 1'b0, 12'h05A);
    // P1: read while empty.
    do_cycle(1'b1, 1'b0, 1'b1, 12'h000);
    do_cycle(1'b1, 1'b0, 1'b1, 12'h000);
    // P2: write and read together while empty (only the write is accepted).
    do_cycle(1'b1, 1'b1, 1'b1, 12'h3C7);
    // P3: fill past full (writes while full are dropped).
    for (i = 0; i < 10; i = i + 1) begin
      next_rand;
      do_cycle(1'b1, 1'b1, 1'b0, rng[11:0]);
    end
    // P4: write and read together at full, then in between.
    for (i = 0; i < 3; i = i + 1) begin
      next_rand;
      do_cycle(1'b1, 1'b1, 1'b1, rng[11:0]);
    end
    // P5: drain past empty.
    for (i = 0; i < 12; i = i + 1) begin
      next_rand;
      do_cycle(1'b1, 1'b0, 1'b1, rng[11:0]);
    end
    // P6: partial fill, then back-to-back streaming in between.
    for (i = 0; i < 3; i = i + 1) begin
      next_rand;
      do_cycle(1'b1, 1'b1, 1'b0, rng[11:0]);
    end
    for (i = 0; i < 10; i = i + 1) begin
      next_rand;
      do_cycle(1'b1, 1'b1, 1'b1, rng[11:0]);
    end
    // P7: random traffic with changing bias, and a reset during traffic.
    for (i = 0; i < 4000; i = i + 1) begin
      phase = (i / 150) % 4;
      if (phase == 0)      begin wthr = 9'd220; rthr = 9'd60;  end
      else if (phase == 1) begin wthr = 9'd60;  rthr = 9'd220; end
      else if (phase == 2) begin wthr = 9'd128; rthr = 9'd128; end
      else                 begin wthr = 9'd256; rthr = 9'd256; end
      if (i == 2000) begin
        for (k = 0; k < 3; k = k + 1) begin
          next_rand;
          do_cycle(1'b1, 1'b1, 1'b0, rng[11:0]);
        end
        for (k = 0; k < 2; k = k + 1) begin
          next_rand;
          do_cycle(1'b0, 1'b1, 1'b1, rng[11:0]);
        end
      end
      next_rand;
      do_cycle(1'b1, ({1'b0, rng[7:0]} < wthr), ({1'b0, rng[15:8]} < rthr), rng[27:16]);
    end

    for (k = 1; k <= 10; k = k + 1) begin
      cover_goal(a_cov[k], 100 + k);
